// Comprehensive health and quality analysis
const vectorHealth = $('Check Vector DB Health').first().json;
const kgHealth = $('Check KG Health').first().json;
const ingestionStats = $('Get Ingestion Statistics').first().json;
const kgValidation = $('Validate KG Integrity').first().json;

const qualityReport = {
  report_id: `quality_${Date.now()}`,
  timestamp: new Date().toISOString(),
  overall_status: 'healthy',

  // System health
  system_health: {
    vector_db: {
      status: vectorHealth.status || 'unknown',
      collections: vectorHealth.collections?.total_collections || 0,
      total_chunks: vectorHealth.collections?.total_chunks || 0,
      estimated_documents: vectorHealth.collections?.estimated_documents || 0,
      issues: []
    },

    knowledge_graph: {
      status: kgHealth.status || 'unknown',
      total_entities: kgHealth.total_entities || 0,
      total_relationships: kgHealth.total_relationships || 0,
      entity_types: Object.keys(kgHealth.entity_types || {}).length,
      relationship_types: Object.keys(kgHealth.relationship_types || {}).length,
      issues: []
    }
  },

  // Data quality metrics
  data_quality: {
    ingestion_stats: {
      total_collections: ingestionStats.total_collections || 0,
      total_chunks: ingestionStats.total_chunks || 0,
      estimated_documents: ingestionStats.estimated_documents || 0,
      last_ingestion: ingestionStats.timestamp || null
    },

    kg_integrity: {
      status: kgValidation.status || 'unknown',
      orphaned_entities: 0,
      duplicate_entities: 0,
      missing_canonical_names: 0,
      issues: kgValidation.issues || [],
      warnings: kgValidation.warnings || []
    }
  },

  // Quality scores
  quality_scores: {
    data_completeness: 0,
    data_consistency: 0,
    system_reliability: 0,
    overall_quality: 0
  },

  alerts: [],
  recommendations: []
};

// Analyze vector DB health
if (vectorHealth.status !== 'healthy') {
  qualityReport.overall_status = 'degraded';
  qualityReport.system_health.vector_db.issues.push('Vector database not healthy');
  qualityReport.alerts.push({
    severity: 'error',
    component: 'vector_db',
    message: 'Vector database health check failed',
    details: vectorHealth
  });
}

// Analyze KG health
if (kgHealth.status !== 'healthy') {
  qualityReport.overall_status = 'degraded';
  qualityReport.system_health.knowledge_graph.issues.push('Knowledge graph not healthy');
  qualityReport.alerts.push({
    severity: 'error',
    component: 'knowledge_graph',
    message: 'Knowledge graph health check failed',
    details: kgHealth
  });
}

// Calculate quality scores
const vectorHealthy = vectorHealth.status === 'healthy' ? 1 : 0;
const kgHealthy = kgHealth.status === 'healthy' ? 1 : 0;
const kgIntegrityHealthy = kgValidation.status === 'healthy' ? 1 : 0;

qualityReport.quality_scores.system_reliability = (vectorHealthy + kgHealthy) / 2;
qualityReport.quality_scores.data_consistency = kgIntegrityHealthy;

// Data completeness based on expected volumes
const minExpectedChunks = 500;
const minExpectedEntities = 100;
const chunkCompleteness = Math.min(1, qualityReport.system_health.vector_db.total_chunks / minExpectedChunks);
const entityCompleteness = Math.min(1, qualityReport.system_health.knowledge_graph.total_entities / minExpectedEntities);
qualityReport.quality_scores.data_completeness = (chunkCompleteness + entityCompleteness) / 2;

// Overall quality score
qualityReport.quality_scores.overall_quality = (
  qualityReport.quality_scores.system_reliability * 0.4 +
  qualityReport.quality_scores.data_consistency * 0.3 +
  qualityReport.quality_scores.data_completeness * 0.3
);

// Round quality scores
Object.keys(qualityReport.quality_scores).forEach(key => {
  qualityReport.quality_scores[key] = Math.round(qualityReport.quality_scores[key] * 1000) / 1000;
});

return { json: qualityReport };
